# phs/baiying/broadcast_reporter.py
from __future__ import annotations

import json
import os
import uuid
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from threading import RLock
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, HTTPException, Query
from fastapi.responses import PlainTextResponse
from pydantic import BaseModel, Field


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _dump(model: BaseModel) -> Dict[str, Any]:
    if hasattr(model, "model_dump"):
        return model.model_dump(exclude_none=True)
    return model.dict(exclude_none=True)


class ProductItem(BaseModel):
    product_id: str
    name: str = ""
    price: Optional[float] = None
    meta: Dict[str, Any] = Field(default_factory=dict)


class SessionCreate(BaseModel):
    title: str = "直播会话"
    start_at: Optional[str] = None
    end_at: Optional[str] = None
    products: List[ProductItem] = Field(default_factory=list)
    comment_count: int = 0
    order_count: int = 0
    meta: Dict[str, Any] = Field(default_factory=dict)


class SessionUpdate(BaseModel):
    title: Optional[str] = None
    start_at: Optional[str] = None
    end_at: Optional[str] = None
    products: Optional[List[ProductItem]] = None
    comment_count: Optional[int] = None
    order_count: Optional[int] = None
    status: Optional[str] = None
    meta: Optional[Dict[str, Any]] = None


class MetricsUpdate(BaseModel):
    peak_online: Optional[int] = None
    avg_stay_seconds: Optional[float] = None
    tts_play_count: Optional[int] = None
    popup_count: Optional[int] = None
    comment_count: Optional[int] = None
    order_count: Optional[int] = None
    custom: Dict[str, Any] = Field(default_factory=dict)


class MetricsDelta(BaseModel):
    online: Optional[int] = None
    tts_play_delta: int = 0
    popup_delta: int = 0
    comment_delta: int = 0
    order_delta: int = 0
    stay_seconds: Optional[float] = None
    custom: Dict[str, Any] = Field(default_factory=dict)


class SessionRecorder:
    def __init__(self, path: Optional[str] = None, max_events: int = 5000):
        default_path = Path("data") / "broadcast_reporter" / "sessions.json"
        self.path = Path(path or os.getenv("PHS_BROADCAST_REPORT_DB", default_path))
        self.max_events = max_events
        self.lock = RLock()
        self.data: Dict[str, Any] = {"sessions": [], "events": []}
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            self._save()
            return
        try:
            self.data = json.loads(self.path.read_text(encoding="utf-8"))
            self.data.setdefault("sessions", [])
            self.data.setdefault("events", [])
        except Exception:
            backup = self.path.with_suffix(".corrupt.json")
            self.path.replace(backup)
            self.data = {"sessions": [], "events": []}
            self._save()

    def _save(self) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def _find_index(self, session_id: str) -> int:
        for i, item in enumerate(self.data["sessions"]):
            if item.get("id") == session_id:
                return i
        return -1

    @staticmethod
    def _default_metrics() -> Dict[str, Any]:
        return {
            "peak_online": 0,
            "avg_stay_seconds": 0.0,
            "stay_samples": [],
            "tts_play_count": 0,
            "popup_count": 0,
            "custom": {},
        }

    def list(self, status: Optional[str] = None, q: Optional[str] = None) -> List[Dict[str, Any]]:
        with self.lock:
            items = deepcopy(self.data["sessions"])
        if status:
            items = [x for x in items if x.get("status") == status]
        if q:
            q_lower = q.lower()
            items = [
                x for x in items
                if q_lower in (x.get("title", "") + json.dumps(x.get("products", []), ensure_ascii=False)).lower()
            ]
        return sorted(items, key=lambda x: x.get("created_at", ""), reverse=True)

    def get(self, session_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(session_id)
            if idx < 0:
                raise KeyError(session_id)
            return deepcopy(self.data["sessions"][idx])

    def create(self, payload: SessionCreate) -> Dict[str, Any]:
        item = _dump(payload)
        item["id"] = uuid.uuid4().hex
        item["start_at"] = item.get("start_at") or _now()
        item["end_at"] = item.get("end_at")
        item["status"] = "running" if not item.get("end_at") else "ended"
        item["metrics"] = self._default_metrics()
        item["created_at"] = _now()
        item["updated_at"] = item["created_at"]
        with self.lock:
            self.data["sessions"].append(item)
            self._save()
        return deepcopy(item)

    def update(self, session_id: str, payload: SessionUpdate) -> Dict[str, Any]:
        patch = _dump(payload)
        with self.lock:
            idx = self._find_index(session_id)
            if idx < 0:
                raise KeyError(session_id)
            item = self.data["sessions"][idx]
            item.update(patch)
            if item.get("end_at") and item.get("status") == "running":
                item["status"] = "ended"
            item["updated_at"] = _now()
            self._save()
            return deepcopy(item)

    def end(self, session_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(session_id)
            if idx < 0:
                raise KeyError(session_id)
            item = self.data["sessions"][idx]
            item["end_at"] = item.get("end_at") or _now()
            item["status"] = "ended"
            item["updated_at"] = _now()
            self._save()
            return deepcopy(item)

    def delete(self, session_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(session_id)
            if idx < 0:
                raise KeyError(session_id)
            item = self.data["sessions"].pop(idx)
            self.data["events"] = [e for e in self.data["events"] if e.get("session_id") != session_id]
            self._save()
            return deepcopy(item)

    def record_event(self, session_id: str, event: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        row = {"id": uuid.uuid4().hex, "session_id": session_id, "event": event, "payload": payload, "created_at": _now()}
        self.data["events"].append(row)
        self.data["events"] = self.data["events"][-self.max_events:]
        return row


class MetricsCollector:
    def __init__(self, recorder: SessionRecorder):
        self.recorder = recorder

    def set_metrics(self, session_id: str, patch: MetricsUpdate) -> Dict[str, Any]:
        data = _dump(patch)
        with self.recorder.lock:
            idx = self.recorder._find_index(session_id)
            if idx < 0:
                raise KeyError(session_id)
            item = self.recorder.data["sessions"][idx]
            metrics = item.setdefault("metrics", SessionRecorder._default_metrics())
            for key in ("peak_online", "avg_stay_seconds", "tts_play_count", "popup_count"):
                if key in data:
                    metrics[key] = data[key]
            if "comment_count" in data:
                item["comment_count"] = int(data["comment_count"])
            if "order_count" in data:
                item["order_count"] = int(data["order_count"])
            metrics.setdefault("custom", {}).update(data.get("custom", {}))
            item["updated_at"] = _now()
            self.recorder.record_event(session_id, "metrics_set", data)
            self.recorder._save()
            return deepcopy(item)

    def add_delta(self, session_id: str, delta: MetricsDelta) -> Dict[str, Any]:
        data = _dump(delta)
        with self.recorder.lock:
            idx = self.recorder._find_index(session_id)
            if idx < 0:
                raise KeyError(session_id)
            item = self.recorder.data["sessions"][idx]
            metrics = item.setdefault("metrics", SessionRecorder._default_metrics())

            if data.get("online") is not None:
                metrics["peak_online"] = max(int(metrics.get("peak_online", 0)), int(data["online"]))
            metrics["tts_play_count"] = int(metrics.get("tts_play_count", 0)) + int(data.get("tts_play_delta", 0))
            metrics["popup_count"] = int(metrics.get("popup_count", 0)) + int(data.get("popup_delta", 0))
            item["comment_count"] = int(item.get("comment_count", 0)) + int(data.get("comment_delta", 0))
            item["order_count"] = int(item.get("order_count", 0)) + int(data.get("order_delta", 0))

            if data.get("stay_seconds") is not None:
                samples = metrics.setdefault("stay_samples", [])
                samples.append(float(data["stay_seconds"]))
                metrics["stay_samples"] = samples[-500:]
                metrics["avg_stay_seconds"] = round(sum(metrics["stay_samples"]) / len(metrics["stay_samples"]), 2)

            metrics.setdefault("custom", {}).update(data.get("custom", {}))
            item["updated_at"] = _now()
            self.recorder.record_event(session_id, "metrics_delta", data)
            self.recorder._save()
            return deepcopy(item)


class ReportGenerator:
    @staticmethod
    def _duration(start_at: Optional[str], end_at: Optional[str]) -> str:
        if not start_at:
            return "-"
        try:
            start = datetime.fromisoformat(start_at.replace("Z", "+00:00"))
            end = datetime.fromisoformat((end_at or _now()).replace("Z", "+00:00"))
            seconds = max(0, int((end - start).total_seconds()))
            h, rem = divmod(seconds, 3600)
            m, s = divmod(rem, 60)
            return f"{h}小时{m}分{s}秒"
        except Exception:
            return "-"

    def generate(self, session: Dict[str, Any]) -> str:
        metrics = session.get("metrics", {})
        products = session.get("products", [])
        product_lines = "\n".join(
            f"- {p.get('name') or p.get('product_id')}｜ID: {p.get('product_id')}｜价格: {p.get('price', '-')}"
            for p in products
        ) or "- 无商品记录"

        comment_count = int(session.get("comment_count", 0))
        order_count = int(session.get("order_count", 0))
        tts_count = int(metrics.get("tts_play_count", 0))
        popup_count = int(metrics.get("popup_count", 0))
        conversion = round(order_count / comment_count * 100, 2) if comment_count else 0.0

        highlights = []
        if order_count > 0:
            highlights.append(f"- 订单转化率约 {conversion}%，可继续复用高频成交话术。")
        if tts_count > popup_count * 3 and popup_count:
            highlights.append("- TTS播放明显高于弹窗次数，可检查是否存在重复播报或话术过密。")
        if not highlights:
            highlights.append("- 暂无明显异常，建议结合录屏与商品点击数据继续复查。")

        return f"""# 直播复盘报告：{session.get('title', '直播会话')}

## 一、基础信息
- 会话ID：{session.get('id')}
- 状态：{session.get('status', '-')}
- 开始时间：{session.get('start_at', '-')}
- 结束时间：{session.get('end_at', '-')}
- 直播时长：{self._duration(session.get('start_at'), session.get('end_at'))}

## 二、商品列表
{product_lines}

## 三、核心数据
| 指标 | 数值 |
|---|---:|
| 评论数 | {comment_count} |
| 订单数 | {order_count} |
| 订单/评论转化率 | {conversion}% |
| 在线峰值 | {metrics.get('peak_online', 0)} |
| 平均停留 | {metrics.get('avg_stay_seconds', 0)} 秒 |
| TTS播放次数 | {tts_count} |
| 弹窗次数 | {popup_count} |

## 四、复盘判断
{chr(10).join(highlights)}

## 五、后续建议
- 保留本场高频成交话术，沉淀到 ScriptWorkbench。
- 对高评论低订单时段复查商品弹窗、价格解释和优惠承接。
- 对TTS过密时段降低播报频率，避免打断主播节奏。
- 对低停留时段复查开场素材、循环片段和商品首屏信息。
"""


def create_broadcast_reporter_router(
    recorder: Optional[SessionRecorder] = None,
    prefix: str = "",
) -> APIRouter:
    session_recorder = recorder or SessionRecorder()
    metrics = MetricsCollector(session_recorder)
    reports = ReportGenerator()
    router = APIRouter(prefix=prefix, tags=["broadcast-reporter"])

    @router.get("/sessions")
    def list_sessions(status: Optional[str] = None, q: Optional[str] = None) -> Dict[str, Any]:
        items = session_recorder.list(status=status, q=q)
        return {"items": items, "count": len(items)}

    @router.post("/sessions")
    def create_session(payload: SessionCreate) -> Dict[str, Any]:
        return session_recorder.create(payload)

    @router.get("/sessions/{session_id}")
    def get_session(session_id: str) -> Dict[str, Any]:
        try:
            return session_recorder.get(session_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="session not found")

    @router.put("/sessions/{session_id}")
    def update_session(session_id: str, payload: SessionUpdate) -> Dict[str, Any]:
        try:
            return session_recorder.update(session_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="session not found")

    @router.delete("/sessions/{session_id}")
    def delete_session(session_id: str) -> Dict[str, Any]:
        try:
            return {"deleted": True, "item": session_recorder.delete(session_id)}
        except KeyError:
            raise HTTPException(status_code=404, detail="session not found")

    @router.post("/sessions/{session_id}/end")
    def end_session(session_id: str) -> Dict[str, Any]:
        try:
            return session_recorder.end(session_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="session not found")

    @router.post("/sessions/{session_id}/metrics")
    def set_session_metrics(session_id: str, payload: MetricsUpdate) -> Dict[str, Any]:
        try:
            return metrics.set_metrics(session_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="session not found")

    @router.post("/sessions/{session_id}/metrics/delta")
    def add_session_metrics(session_id: str, payload: MetricsDelta) -> Dict[str, Any]:
        try:
            return metrics.add_delta(session_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="session not found")

    @router.get("/sessions/{session_id}/report", response_class=PlainTextResponse)
    def get_session_report(session_id: str, format: str = Query(default="markdown")) -> str:
        if format not in ("markdown", "md"):
            raise HTTPException(status_code=400, detail="only markdown report is supported")
        try:
            return reports.generate(session_recorder.get(session_id))
        except KeyError:
            raise HTTPException(status_code=404, detail="session not found")

    return router


class BroadcastReporterProvider:
    provider_id = "broadcast_reporter"
    name = "Broadcast Reporter"
    version = "0.1.0"

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.recorder = SessionRecorder(self.config.get("db_path"))
        self.metrics = MetricsCollector(self.recorder)
        self.reporter = ReportGenerator()
        self.router = create_broadcast_reporter_router(self.recorder)

    def get_router(self) -> APIRouter:
        return self.router

    def health(self) -> Dict[str, Any]:
        return {
            "provider": self.provider_id,
            "ok": True,
            "db_path": str(self.recorder.path),
            "session_count": len(self.recorder.list()),
        }

    def metadata(self) -> Dict[str, Any]:
        return {
            "id": self.provider_id,
            "name": self.name,
            "version": self.version,
            "routes": [
                "/sessions",
                "/sessions/{id}/metrics",
                "/sessions/{id}/metrics/delta",
                "/sessions/{id}/report",
            ],
        }


def create_provider(config: Optional[Dict[str, Any]] = None) -> BroadcastReporterProvider:
    return BroadcastReporterProvider(config)


provider = BroadcastReporterProvider()
router = provider.get_router()

